INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-advanced-17','ADVANCED-17','Nâng cao · Đề 17','advanced','Nâng cao',60,'published',1,'Đề luyện nâng cao số 17 do Nhà Hán Ngữ biên soạn phục vụ tự học và tự đánh giá.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-advanced-17-q01','seed-advanced-17',1,'single_choice','Chọn bản dịch phù hợp nhất: 学习计划应根据实际情况不断调整。','Câu gốc: 学习计划应根据实际情况不断调整。 Nghĩa phù hợp: Kế hoạch học tập nên được điều chỉnh liên tục theo tình hình thực tế. Dạng bài tập này yêu cầu đọc toàn câu và xác định trọng tâm thay vì dịch từng từ rời rạc.',NULL,NULL,0,1,'',datetime('now')),
('seed-advanced-17-q02','seed-advanced-17',2,'single_choice','Chọn bản dịch phù hợp nhất: 面对变化时，保持灵活性往往比机械执行更重要。','Câu gốc: 面对变化时，保持灵活性往往比机械执行更重要。 Nghĩa phù hợp: Khi đối mặt thay đổi, giữ sự linh hoạt thường quan trọng hơn thực hiện máy móc. Dạng bài tập này yêu cầu đọc toàn câu và xác định trọng tâm thay vì dịch từng từ rời rạc.',NULL,NULL,0,1,'',datetime('now')),
('seed-advanced-17-q03','seed-advanced-17',3,'single_choice','Chọn bản dịch phù hợp nhất: 评价一个方案时，需要同时考虑成本、效果和可持续性。','Câu gốc: 评价一个方案时，需要同时考虑成本、效果和可持续性。 Nghĩa phù hợp: Khi đánh giá một phương án, cần đồng thời xem xét chi phí, hiệu quả và tính bền vững. Dạng bài tập này yêu cầu đọc toàn câu và xác định trọng tâm thay vì dịch từng từ rời rạc.',NULL,NULL,0,1,'',datetime('now')),
('seed-advanced-17-q04','seed-advanced-17',4,'single_choice','Chọn bản dịch phù hợp nhất: 信息越多并不一定意味着判断越准确。','Câu gốc: 信息越多并不一定意味着判断越准确。 Nghĩa phù hợp: Thông tin càng nhiều không nhất thiết đồng nghĩa phán đoán càng chính xác. Dạng bài tập này yêu cầu đọc toàn câu và xác định trọng tâm thay vì dịch từng từ rời rạc.',NULL,NULL,0,1,'',datetime('now')),
('seed-advanced-17-q05','seed-advanced-17',5,'single_choice','Chọn bản dịch phù hợp nhất: 真正的理解通常来自反复应用和修正。','Câu gốc: 真正的理解通常来自反复应用和修正。 Nghĩa phù hợp: Sự hiểu thật sự thường đến từ việc áp dụng và điều chỉnh lặp lại. Dạng bài tập này yêu cầu đọc toàn câu và xác định trọng tâm thay vì dịch từng từ rời rạc.',NULL,NULL,0,1,'',datetime('now')),
('seed-advanced-17-q06','seed-advanced-17',6,'single_choice','Chọn bản dịch phù hợp nhất: 团队合作的关键之一是让责任和预期保持清晰。','Câu gốc: 团队合作的关键之一是让责任和预期保持清晰。 Nghĩa phù hợp: Một chìa khóa của hợp tác nhóm là giữ trách nhiệm và kỳ vọng rõ ràng. Dạng bài tập này yêu cầu đọc toàn câu và xác định trọng tâm thay vì dịch từng từ rời rạc.',NULL,NULL,0,1,'',datetime('now')),
('seed-advanced-17-q07','seed-advanced-17',7,'single_choice','Chọn bản dịch phù hợp nhất: 在复杂任务中，明确目标有助于提高整体效率。','Câu gốc: 在复杂任务中，明确目标有助于提高整体效率。 Nghĩa phù hợp: Trong nhiệm vụ phức tạp, xác định rõ mục tiêu giúp nâng cao hiệu quả tổng thể. Dạng bài tập này yêu cầu đọc toàn câu và xác định trọng tâm thay vì dịch từng từ rời rạc.',NULL,NULL,0,1,'',datetime('now')),
('seed-advanced-17-q08','seed-advanced-17',8,'single_choice','Chọn bản dịch phù hợp nhất: 有效沟通不仅需要表达，也需要认真倾听。','Câu gốc: 有效沟通不仅需要表达，也需要认真倾听。 Nghĩa phù hợp: Giao tiếp hiệu quả không chỉ cần diễn đạt mà còn cần lắng nghe nghiêm túc. Dạng bài tập này yêu cầu đọc toàn câu và xác định trọng tâm thay vì dịch từng từ rời rạc.',NULL,NULL,0,1,'',datetime('now')),
